<?php
if(PHP_SAPI!=='cli')exit(1);ob_start();require_once __DIR__.'/../koneksi.php';require_once __DIR__.'/http_form_scope.php';spp_test_assert_database_target($koneksi);require_once __DIR__.'/../includes/legacy_import_http.php';require_once __DIR__.'/legacy_finance_support.php';
$root=dirname(getenv('SPP_TEST_ISOLATED_INSTANCE'));$full=json_decode(file_get_contents($root.'/workflow-browser.json'),true);$finance=json_decode(file_get_contents($root.'/finance-browser.json'),true);$base=rtrim(getenv('SPP_TEST_BASE_URL'),'/');spp_test_assert_http_clone($base,DB_NAME);$actor=(int)lf_one($koneksi,"SELECT id FROM admin WHERE role='super_admin' AND is_active=1 LIMIT 1")['id'];
function lui_session(int $actor,int $unit,string $role='super_admin'): string {$sid='legacyui'.bin2hex(random_bytes(10));session_id($sid);session_start();$_SESSION=['admin_id'=>$actor,'admin_role'=>$role,'active_unit_id'=>$unit,'csrf_legacy_import'=>str_repeat('a',64),'csrf_legacy_finance'=>str_repeat('a',64)];session_write_close();return $sid;}
function lui_http(string $path,string $sid='',?array $post=null,bool $multipart=false): array {global $base;$c=curl_init($base.'/'.$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_TIMEOUT=>180,CURLOPT_COOKIE=>'PHPSESSID='.$sid]);if($post!==null){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,$multipart?$post:http_build_query($post));} $body=curl_exec($c);if($body===false)throw new RuntimeException(curl_error($c));$status=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);return [$status,$body];}
function lui_worker(string $suffix): void {global $root;$p=proc_open([PHP_BINARY,'-d','memory_limit=768M',__DIR__.'/../scripts/legacy_worker.php','--once'],[0=>['pipe','r'],1=>['file',$root.'/ui-worker-'.$suffix.'.out','w'],2=>['file',$root.'/ui-worker-'.$suffix.'.err','w']],$pipes);fclose($pipes[0]);lft_assert(proc_close($p)===0,'Native queue worker failed');}
$sid=lui_session($actor,1);$fullSid=$full['session'];$job=$full['job'];$review=$finance['review'];
foreach(['legacy_import.php','legacy_full.php','legacy_finance.php','backup_restore.php?tab=legacy'] as $path)lft_assert(lui_http($path)[0]>=300,'Anonymous UI access');
foreach(['admin','kasir','bendahara'] as $role){$other=(int)lf_one($koneksi,'SELECT id FROM admin WHERE role=? AND is_active=1 LIMIT 1',[$role])['id'];$otherSid=lui_session($other,1,$role);foreach(['legacy_import.php','legacy_finance.php','legacy_full.php'] as $path)lft_assert(in_array(lui_http($path,$otherSid)[0],[302,403],true),'Non-SA native UI '.$path);lft_assert(lui_http('legacy_finance_api.php?action=student_search&q=SISWA',$otherSid)[0]===403,'Non-SA student search');}
[$status,$html]=lui_http('backup_restore.php?tab=legacy',$sid);lft_assert($status===200&&substr_count($html,'class="legacy-goal ')===3&&!str_contains($html,'id="panel-legacy" class="legacy-ui" role="tabpanel" aria-labelledby="tab-legacy" hidden'),'Native landing cards');
foreach(['review','exceptions','confirm','result'] as $step){[$status,$html]=lui_http('legacy_full.php?id='.$job.'&step='.$step,$fullSid);lft_assert($status===200&&!str_contains($html,'Fatal error'),'GET wizard step');lft_assert(($step==='review')===str_contains($html,'id="transition-settings"'),'Unrelated full form rendered');}
foreach(['students','components','savings','obligations'] as $section){[$status,$html]=lui_http('legacy_full.php?id='.$job.'&step=exceptions&section='.$section.'&student=9710000001',$fullSid);lft_assert($status===200,'Exception view');lft_assert(($section==='students')===str_contains($html,'name="nis"'),'Student fields leaked');lft_assert(($section==='obligations')===str_contains($html,'name="obligations_attested"'),'Obligation fields leaked');lft_assert(($section==='savings')===str_contains($html,'name="savings_attested"'),'Savings fields leaked');}
[$status,$html]=lui_http('legacy_full.php?id='.$job.'&step=exceptions&section=students&group_class=ALUMNI',$fullSid);lft_assert(str_contains($html,'SISWA UJI 3 · NIS 9710000003')&&!str_contains($html,'value="9710000001" >'),'GET group membership');
$d=lful_draft($job);$post=['action'=>'preview_group','id'=>$job,'version'=>$d['version'],'csrf_token'=>str_repeat('a',64),'view_step'=>'exceptions','view_section'=>'obligations','group_type'=>'obligations','source_class'=>'ALUMNI','group_evidence'=>'Native input survives preview cancellation.','obligations_confirmed'=>'1'];
[$status,$html]=lui_http('legacy_full.php?id='.$job.'&step=exceptions&section=obligations',$fullSid,$post);lft_assert($status===200&&str_contains($html,'Sebelum → Sesudah')&&!str_contains($html,'&quot;sebelum&quot;'),'Human preview');preg_match('/name="group" value="([^"]*)"/',$html,$m);$group=html_entity_decode($m[1]??'',ENT_QUOTES,'UTF-8');lft_assert($group!=='','Back preview payload');[$status,$html]=lui_http('legacy_full.php?id='.$job.'&step=exceptions&section=obligations',$fullSid,['action'=>'back_group','id'=>$job,'version'=>$d['version'],'csrf_token'=>str_repeat('a',64),'group'=>$group,'view_step'=>'exceptions','view_section'=>'obligations']);lft_assert($status===200&&str_contains($html,'Native input survives preview cancellation.')&&lful_draft($job)['version']===$d['version'],'Back editing changed draft or lost input');
foreach(['step[]=x','step=bad','section[]=x','section=bad'] as $q)lft_assert(lui_http('legacy_full.php?'.$q,$fullSid)[0]===400,'Invalid wizard parameter');
[$status,$json]=lui_http('legacy_finance_api.php?action=student_search&q=SISWA',$sid);$found=json_decode($json,true);lft_assert($status===200&&isset($found['students']),'Student search');foreach($found['students'] as $student){unit_set_context($koneksi,1);lft_assert((int)lf_one($koneksi,'SELECT unit_id FROM siswa WHERE id=?',[$student['id']])['unit_id']===1,'Search unit leak');}lft_assert(lui_http('legacy_finance_api.php?action=student_search&q[]=x',$sid)[0]===400,'Invalid student search');
foreach(['archive','reviews'] as $tab){[$status,$html]=lui_http('legacy_finance.php?tab='.$tab,$sid);lft_assert($status===200&&(($tab==='archive')===str_contains($html,'<h2>Arsip Sumber</h2>')),'Archive/review separation');}
[$status,$html]=lui_http('legacy_finance.php?tab=reviews&review='.$review.'&student_q=SISWA',$sid);lft_assert($status===200&&str_contains($html,'Saldo Sumber')&&str_contains($html,'Hasil Jurnal')&&str_contains($html,'Selisih')&&!str_contains($html,'list="lf-target-students"'),'Identity lookup and balances');
// Real native multipart upload, source examination, final confirmation and result.
$native=[];
foreach(['students','finance'] as $category){
    lui_worker('health-'.$category);
    $upload=['action'=>'upload','request_key'=>bin2hex(random_bytes(16)),'category'=>$category,'unit'=>'1','csrf_token'=>str_repeat('a',64),'backup'=>new CURLFile('C:/Users/lakch/Downloads/SD-5.dat','application/octet-stream','SD-5.dat')];
    lft_assert(lui_http('legacy_import.php?mode='.$category,$sid,array_replace($upload,['csrf_token'=>'wrong']),true)[0]===403,'Native upload CSRF');lui_worker('health-refresh-'.$category);lui_worker('health-fresh-'.$category);
    [$status,$html]=lui_http('legacy_import.php?mode='.$category,$sid,$upload,true);lft_assert($status===302,'Native upload failed: '.$status.' '.strip_tags(substr($html,0,300)));
    $beforeRetry=(int)legacy_queue()->query('SELECT COUNT(*) FROM jobs')->fetchColumn();lft_assert(lui_http('legacy_import.php?mode='.$category,$sid,$upload,true)[0]===302,'Native upload retry');lft_assert((int)legacy_queue()->query('SELECT COUNT(*) FROM jobs')->fetchColumn()===$beforeRetry,'Upload retry created another job');
    $q=legacy_queue()->prepare('SELECT * FROM jobs WHERE category=? AND name=? ORDER BY created DESC,rowid DESC LIMIT 1');$q->execute([$category,'SD-5.dat']);$j=$q->fetch(PDO::FETCH_ASSOC);lui_worker('source-'.$category);$j=legacy_job($j['id']);lft_assert($j['state']==='ready','Actual source not ready: '.$j['message']);
    [$status,$html]=lui_http('legacy_import.php?id='.$j['id'].'&step=confirm',$sid);lft_assert($status===200&&str_contains($html,'Konfirmasi Impor'),'Native confirmation missing');
    lft_assert(lui_http('legacy_import.php?id='.$j['id'],$sid,['action'=>'confirm','id'=>$j['id'],'csrf_token'=>str_repeat('a',64),'confirmation'=>'IMPOR LEGACY'])[0]===302,'Native confirmation');lui_worker('apply-'.$category);lft_assert(legacy_job($j['id'])['state']==='imported','Native import not published');
    [$status,$html]=lui_http('legacy_import.php?id='.$j['id'].'&step=result',$sid);lft_assert($status===200&&str_contains($html,$category==='students'?'Aktifkan Siswa Legacy':'Tinjau Saldo &amp; Tunggakan'),'Native result links');
    lft_assert(lui_http('legacy_import.php?id='.$j['id'],lui_session($actor,2))[0]===403,'Native cross-unit job');
    lft_assert(lui_http('legacy_import.php?id='.$j['id'],$sid,['action'=>'confirm','id'=>$j['id'],'csrf_token'=>str_repeat('a',64),'confirmation'=>'IMPOR LEGACY'])[0]===409,'Duplicate confirmation');
    $native[$category]=$j['id'];
}
file_put_contents($root.'/ui-browser.json',lf_json(['base'=>$base,'session'=>$sid,'full_session'=>$fullSid,'job'=>$job,'review'=>$review,'students'=>$native['students'],'finance'=>$native['finance'],'actor'=>$actor]));
echo "PASS: native landing/steps/sections, exact group back-edit, role/unit/CSRF/search, separated archives, real SD .dat student and finance upload/examination/confirmation/application/results without JavaScript.\n";
